<?php use CmuLms\View; $title='Attendance monitor'; include __DIR__.'/../layout/header.php'; $present=array_values(array_filter($roster,fn($r)=>($r['status']??'')==='present')); $late=array_values(array_filter($roster,fn($r)=>($r['status']??'')==='late')); $unsubmitted=array_values(array_filter($roster,fn($r)=>empty($r['status']))); ?>
<section class="hero"><span><?=View::e($session['code'])?> · Attendance monitor</span><h1><?=View::e($session['title'])?></h1><p><?=View::e($session['opens_at'])?> to <?=View::e($session['closes_at'])?></p></section>
<section class="grid"><a class="card" href="#assigned"><h2><?=count($roster)?></h2><p>Assigned</p></a><a class="card" href="#present"><h2><?=count($present)?></h2><p>Present</p></a><a class="card" href="#late"><h2><?=count($late)?></h2><p>Late</p></a><a class="card" href="#unsubmitted"><h2><?=count($unsubmitted)?></h2><p>Unsubmitted</p></a></section>
<section class="card" id="assigned"><h2>Student check-ins</h2><div class="grid"><?php foreach($roster as $student): ?><article class="card"><h3><?=View::e($student['name'])?></h3><p><?=View::e($student['id_number'])?> · <span class="badge"><?=View::e($student['status']??'unsubmitted')?></span></p><?php if(!empty($student['photo_path'])): ?><img src="?route=attendance-photo&amp;id=<?=View::e($student['id'])?>" alt="Attendance photo for <?=View::e($student['name'])?>" style="width:100%;max-width:280px;border-radius:10px"><p><small><?=View::e($student['submitted_at'])?></small></p><?php else: ?><p class="muted">No attendance image submitted.</p><?php endif; ?></article><?php endforeach; ?><?php if(!$roster): ?><p>No enrolled students found.</p><?php endif; ?></div></section>
<?php include __DIR__.'/../layout/footer.php'; ?>
